Parameters
    A: Population of agents (particles)
    f(): fitness function
Algorithm: to find an optimal value (location of food/shelter)
    A = Particle_Initialization(); //random generated solutions
    do 
         for each particle p in A do {
              fp = f(p); 
              if fp is better than f(pBest)
                  pBest = p; //pBest is the best p so far
         }
         gBest = pBest that is best p in A; //best p for the swarm

         for each particle p in A { //update all agents in the population
              v = v + c1*rand*(pBest – p) + c2*rand*(gBest – p);
              p = p + v;  //position update by v
         }
    until termination condition
